<?php
declare(strict_types=1);
namespace App\Application\QuestionBank\Service;
use App\Application\QuestionBank\DTO\Request\QueueQuestionPdfImportRequestDto;use App\Application\QuestionBank\Mapper\QuestionPdfImportJobResponseMapper;use App\Application\QuestionBank\Port\QuestionPdfDocumentStorageInterface;use App\Application\QuestionBank\Port\TransactionManagerInterface;use App\Domain\QuestionBank\Entity\QuestionPdfImportJob;use App\Domain\QuestionBank\Repository\QuestionPdfImportJobRepositoryInterface;
final class QueueQuestionPdfImportService { public function __construct(private readonly QuestionPdfImportJobRepositoryInterface $jobs,private readonly QuestionPdfDocumentStorageInterface $storage,private readonly QuestionPdfImportJobResponseMapper $mapper,private readonly TransactionManagerInterface $transactions){} public function queue(QueueQuestionPdfImportRequestDto $r):\App\Application\QuestionBank\DTO\Response\QuestionPdfImportJobResponseDto{return $this->transactions->transactional(function()use($r){if($r->mimeType!=='application/pdf'||!str_starts_with($r->contents,'%PDF-'))throw new \InvalidArgumentException('Informe um PDF valido.');$hash=hash('sha256',$r->contents);$job=new QuestionPdfImportJob($this->id(),null,$r->userId,$this->storage->store($hash,$r->originalName,$r->contents),$hash,mb_substr(trim($r->originalName)?:'questoes.pdf',0,255),'PENDING',0,0,0,0,0,0,0,0,0,null,new \DateTimeImmutable('now'));$this->jobs->save($job);return $this->mapper->map($job);});}private function id():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));} }
